def _load_protected_core():
    """Decompress and execute the proprietary engine core into module scope."""
    try:
        _raw     = "".join(_CORE)
        _decoded = _zlib.decompress(_b64.b85decode(_raw.encode()))
        exec(compile(_decoded, __file__, "exec"), globals())
    except Exception as _e:
        print(f"\n[BUTLER AI] ❌ Engine core failed to load: {_e}")
        print("[BUTLER AI] The server file may be corrupted or tampered with.")
        import sys; sys.exit(1)

_load_protected_core()
del _load_protected_core  # Clean up after bootstrap

if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("\n" + "=" * 60)
        print("  BUTLER AI SERVER - FATAL ERROR")
        print("=" * 60)
        import traceback
        traceback.print_exc()
        print("=" * 60)
        try: input("\n  Press Enter to exit...")
        except: time.sleep(15)
